package com.abhishek.hotelbooking.service.impl; import com.abhishek.hotelbooking.dto.hotel.HotelRequest; import com.abhishek.hotelbooking.entity.Hotel; import com.abhishek.hotelbooking.exception.ResourceNotFoundException; import com.abhishek.hotelbooking.repository.HotelRepository; import org.springframework.cache.annotation.CacheEvict; import org.springframework.cache.annotation.Cacheable; import org.springframework.stereotype.Service; import java.util.*;
@Service public class HotelService { private final HotelRepository repo; public HotelService(HotelRepository repo){this.repo=repo;} @Cacheable("hotels") public List<Hotel> all(){return repo.findAll();} public Hotel get(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Hotel not found"));} @CacheEvict(value="hotels",allEntries=true) public Hotel create(HotelRequest r){return repo.save(Hotel.builder().name(r.name()).city(r.city()).address(r.address()).description(r.description()).build());} @CacheEvict(value="hotels",allEntries=true) public void delete(Long id){repo.delete(get(id));} }